\begin{axis}
[
axis lines=middle,
tick style={draw=none},
axis line style = thick,
  xmin=-4.5,
  xmax=1.5,
  ymin=-3.5,
  ymax=3.5,
  xlabel=$x$,
  ylabel=$y$,
xtick={\empty},
ytick={\empty},
xlabel style={right},
ylabel style={above},
%axis equal 
]  

\plot[domain=-1.5:-0.5, samples=100, color=red, line width=0.6pt, smooth, dotted, opacity=0.75] {-2*(x+1)^3+1};
