\node[left, red] at (axis cs:1.5,-1) {$y=f(x)-3$};

\plot[domain=1.5:2.5, samples=100, color=blue, line width=0.6pt, smooth, dotted, opacity=0.75] {-2*(x-2)^3+3};
\filldraw[draw=none,blue] (axis cs:2,3) circle (2pt) node[above right, font=\small, color=black] {$(2,3)$};
\node[left, blue] at (axis cs:1.5,3) {$y=f(x)+1$};

\draw[-stealth, blue, shorten > = 3pt, shorten <    = 3pt] (axis cs:2,-1) -- (axis cs:2,3) node[midway, left, pos=0.5] {\small $+4$};

